<?php require __DIR__.'/../includes/bootstrap.php';require_admin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$data=[(int)($_POST['category_id']??0)?:null,trim($_POST['name']??''),trim($_POST['description']??''),(float)($_POST['price']??0),trim($_POST['image_url']??''),(int)($_POST['stock']??0),isset($_POST['is_active'])?1:0];if($id){$data[]=$id;db()->prepare('UPDATE products SET category_id=?,name=?,description=?,price=?,image_url=?,stock=?,is_active=? WHERE id=?')->execute($data);}else db()->prepare('INSERT INTO products(category_id,name,description,price,image_url,stock,is_active) VALUES(?,?,?,?,?,?,?)')->execute($data);$msg='تم حفظ المنتج.';}if($action==='delete'){db()->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_POST['id']]);$msg='تم حذف المنتج.';}}$edit=null;if(isset($_GET['edit'])){$s=db()->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$cats=db()->query('SELECT id,name FROM categories ORDER BY sort_order')->fetchAll();$items=db()->query('SELECT p.*,c.name cat FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>المنتجات</title><link rel="stylesheet" href="../assets/css/store.css"></head><body><main class="inner"><a href="index.php">← لوحة التحكم</a><h1>إدارة المنتجات</h1><?php if($msg):?><p class="notice"><?=h($msg)?></p><?php endif?><form method="post" class="admin-form"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><label>اسم المنتج<input name="name" required value="<?=h($edit['name']??'')?>"></label><label>القسم<select name="category_id"><option value="">بدون قسم</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=isset($edit['category_id'])&&(int)$edit['category_id']===$c['id']?'selected':''?>><?=h($c['name'])?></option><?php endforeach?></select></label><label>السعر<input type="number" step=".01" min="0" name="price" required value="<?=h($edit['price']??'0')?>"></label><label>المخزون<input type="number" min="0" name="stock" value="<?=h($edit['stock']??'0')?>"></label><label>رابط الصورة<input name="image_url" value="<?=h($edit['image_url']??'')?>"></label><label>الوصف<textarea name="description"><?=h($edit['description']??'')?></textarea></label><label><input type="checkbox" name="is_active" <?=!isset($edit['is_active'])||(int)$edit['is_active']===1?'checked':''?>> منشور</label><button class="gold">حفظ المنتج</button></form><div class="table-wrap"><table><tr><th>المنتج</th><th>القسم</th><th>السعر</th><th>المخزون</th><th>الإجراءات</th></tr><?php foreach($items as $p):?><tr><td><?=h($p['name'])?></td><td><?=h($p['cat'])?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td><td><a href="?edit=<?=$p['id']?>">تعديل</a><form method="post" class="inline"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button>حذف</button></form></td></tr><?php endforeach?></table></div></main></body></html>